 /** Parse a port list into merged, sorted ranges. See README.md for the rules. */
 export function parsePorts(list: string): PortRange[] {
-  throw new Error("not implemented");
+  if (list.trim() === "") {
+    return [];
+  }
+
+  const ranges: PortRange[] = [];
+  for (const item of list.split(",")) {
+    if (item.trim() === "") {
+      throw new Error("malformed port list");
+    }
+
+    const parts = item.split("-");
+    if (parts.length > 2) {
+      throw new Error("malformed port list");
+    }
+
+    const from = parsePort(parts[0]?.trim());
+    const to = parts.length === 1 ? from : parsePort(parts[1]?.trim());
+    if (to < from) {
+      throw new Error("malformed port list");
+    }
+
+    ranges.push([from, to]);
+  }
+
+  ranges.sort((left, right) => left[0] - right[0]);
+
+  const merged: PortRange[] = [];
+  for (const [from, to] of ranges) {
+    const prev = merged[merged.length - 1];
+    if (!prev || from > prev[1] + 1) {
+      merged.push([from, to]);
+      continue;
+    }
+
+    if (to > prev[1]) {
+      prev[1] = to;
+    }
+  }
+
+  return merged;
 }

 /** The canonical text form of a port list. See README.md. */
 export function normalizePorts(list: string): string {
-  throw new Error("not implemented");
+  return parsePorts(list)
